#!/usr/bin/env python3
"""Consistency checks for the GitBook in docs/gitbook.

0. No template tags other than the {% hint %} callouts (they break both renderers).
1. Every relative Markdown link points to an existing file, and every #anchor
   matches a heading in the target page (GitBook slug rules).
2. Every page is listed in SUMMARY.md, and every SUMMARY entry exists.
3. Every <img src> resolves, every SVG asset is referenced and is well-formed XML.
4. The diagram generators in docs/diagrams reproduce the committed SVGs exactly.

Run from the repository root: python3 .github/scripts/check_book.py
"""
import filecmp
import glob
import os
import re
import subprocess
import sys
import tempfile
import xml.dom.minidom

BOOK = 'docs/gitbook'
ASSETS = os.path.join(BOOK, '.gitbook', 'assets')
DIAGRAMS = 'docs/diagrams'
errors = []


def error(msg):
    errors.append(msg)
    # GitHub Actions annotation; plain text elsewhere.
    print(f'::error::{msg}' if os.environ.get('GITHUB_ACTIONS') else f'ERROR: {msg}')


def slug(heading):
    heading = re.sub(r'[^\w\s-]', '', heading.strip().lower())
    return re.sub(r'\s+', '-', heading)


pages = sorted(glob.glob(f'{BOOK}/**/*.md', recursive=True))
pages = [p for p in pages if '/.gitbook/' not in p]
anchors = {os.path.normpath(p): {slug(h) for h in re.findall(r'(?m)^#+\s+(.*)$', open(p).read())} for p in pages}

# 0. template tags: GitBook and HonKit both treat {% ... %} as template syntax, even
#    inside code spans, so only the hint callout tags may appear.
for page in pages:
    for n, line in enumerate(open(page).read().split('\n'), 1):
        for tag in re.findall(r'{%.*?%}', line):
            if not re.fullmatch(r'{%\s*(hint\s+style="(info|warning|danger|success)"|endhint)\s*%}', tag):
                error(f'{page}:{n}: template tag {tag} is not allowed (only hint callouts); rephrase it')

# 1. links and anchors
for page in pages:
    text = open(page).read()
    for link in re.findall(r'\]\(([^)\s]+)\)', text):
        if re.match(r'^[a-z]+:', link):
            continue
        path, _, frag = link.partition('#')
        target = os.path.normpath(os.path.join(os.path.dirname(page), path)) if path else os.path.normpath(page)
        if not os.path.exists(target):
            error(f'{page}: broken link {link}')
        elif frag and target.endswith('.md') and frag not in anchors.get(target, set()):
            error(f'{page}: unknown anchor {link}')

# 2. SUMMARY coverage
summary_path = os.path.join(BOOK, 'SUMMARY.md')
listed = {os.path.normpath(os.path.join(BOOK, l)) for l in re.findall(r'\]\(([^)]+)\)', open(summary_path).read())}
for page in pages:
    if os.path.normpath(page) != os.path.normpath(summary_path) and os.path.normpath(page) not in listed:
        error(f'{page}: not listed in SUMMARY.md')
for entry in listed:
    if not os.path.exists(entry):
        error(f'SUMMARY.md: entry {entry} does not exist')

# 3. images and SVG assets
referenced = set()
for page in pages:
    for src in re.findall(r'<img src="([^"]+)"', open(page).read()) + re.findall(r'!\[[^\]]*\]\(([^)\s]+)\)', open(page).read()):
        if re.match(r'^[a-z]+:', src):
            continue
        target = os.path.normpath(os.path.join(os.path.dirname(page), src))
        referenced.add(target)
        if not os.path.exists(target):
            error(f'{page}: missing image {src}')
for svg in sorted(glob.glob(f'{ASSETS}/*.svg')):
    if os.path.normpath(svg) not in referenced:
        error(f'{svg}: not used by any page')
    try:
        xml.dom.minidom.parse(svg)
    except Exception as exc:  # noqa: BLE001 - report any parse failure
        error(f'{svg}: invalid XML ({exc})')

# 4. diagrams are reproducible from their generators
with tempfile.TemporaryDirectory() as out:
    for script in ('ug.py', 'dg.py'):
        result = subprocess.run([sys.executable, os.path.join(DIAGRAMS, script), out], capture_output=True, text=True)
        if result.returncode != 0:
            error(f'{DIAGRAMS}/{script} failed: {result.stderr.strip()}')
    generated = {os.path.basename(f) for f in glob.glob(f'{out}/*.svg')}
    committed = {os.path.basename(f) for f in glob.glob(f'{ASSETS}/*.svg')}
    for name in sorted(generated - committed):
        error(f'{name}: generated by docs/diagrams but not committed')
    for name in sorted(committed - generated):
        error(f'{name}: committed but no generator produces it')
    for name in sorted(generated & committed):
        if not filecmp.cmp(os.path.join(out, name), os.path.join(ASSETS, name), shallow=False):
            error(f'{name}: out of date; run python3 docs/diagrams/ug.py|dg.py {ASSETS}')

print(f'Checked {len(pages)} pages and {len(glob.glob(f"{ASSETS}/*.svg"))} SVGs: '
      f'{"OK" if not errors else f"{len(errors)} problem(s)"}')
sys.exit(1 if errors else 0)
